const body = $json.body || $json;
const required = ['curso_id', 'student_id', 'conversation_id', 'message', 'requested_mode'];
for (const field of required) {
  if (body[field] === undefined || body[field] === null || String(body[field]).trim() === '') throw new Error(`Falta el campo requerido: ${field}`);
}
const modes = ['chat', 'socratico', 'recursos'];
if (!modes.includes(body.requested_mode)) throw new Error('requested_mode debe ser chat, socratico o recursos');
return [{ json: {
  institucion_id: body.institucion_id ? String(body.institucion_id) : null,
  curso_id: Number(body.curso_id),
  curso_nombre: body.curso_nombre || `Curso ${body.curso_id}`,
  student_id: String(body.student_id),
  conversation_id: String(body.conversation_id),
  message: String(body.message).trim(),
  requested_mode: body.requested_mode,
  chatbot_prompt: body.chatbot_prompt || 'Eres un tutor académico claro, respetuoso y riguroso.',
  chatbot_temperature: Number(body.chatbot_temperature ?? 0.2),
  extend_knowledge: Boolean(body.extend_knowledge),
  namespace: `curso_${body.curso_id}`
} }];

const input = $('Validar contrato del backend').item.json;
const matches = Array.isArray($json.matches) ? $json.matches : [];
const sources = matches.filter((match) => match.metadata?.texto).map((match) => ({ texto: match.metadata.texto, archivo: match.metadata.archivo || 'Material del curso', pagina: match.metadata.pagina ?? null }));
const citations = sources.map(({ archivo, pagina }) => ({ archivo, pagina }));
const context = sources.map((source, index) => `[${index + 1}] ${source.texto}`).join('

');
let instruction = 'Responde de forma clara, didáctica y concisa. Si no hay contexto suficiente, indícalo con honestidad.';
if (input.requested_mode === 'socratico') instruction = 'Guía al estudiante mediante preguntas y pistas. No reveles la solución completa inmediatamente.';
if (input.requested_mode === 'recursos') instruction = 'Entrega un recurso estructurado con resumen, conceptos clave, ejemplo y dos preguntas de práctica.';
return [{ json: { ...input, citations, prompt: `${input.chatbot_prompt}

${instruction}

Curso: ${input.curso_nombre}.

Material recuperado:
${context || 'No se recuperó material relevante.'}

Solicitud del estudiante: ${input.message}` } }];

const context = $('Construir contexto y prompt').item.json;
const respuesta = $json.choices?.[0]?.message?.content || 'No fue posible generar una respuesta en este momento.';
return [{ json: { respuesta, citas: context.citations, usage: $json.usage || null, curso_id: context.curso_id, conversation_id: context.conversation_id } }];
